package com.chronos.education.grade.controller;
import com.chronos.commons.model.ResultData; import com.chronos.education.grade.model.CourseGrade; import com.chronos.education.grade.service.GradeCenterService; import com.chronos.education.scheduling.dao.EducationUserBindingRepository; import java.util.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/portal/education/grades") public class GradePortalController { private final GradeCenterService service; private final EducationUserBindingRepository bindings; public GradePortalController(GradeCenterService service,EducationUserBindingRepository bindings){this.service=service;this.bindings=bindings;} @GetMapping public ResultData<List<CourseGrade>> list(Authentication a){return ResultData.<List<CourseGrade>>builder().code("200").msg("ok").data(service.studentGrades(studentId(a))).build();} @GetMapping("/{id}") public ResultData<CourseGrade> detail(@PathVariable String id,Authentication a){return ResultData.<CourseGrade>builder().code("200").msg("ok").data(service.studentGrade(id,studentId(a))).build();} private String studentId(Authentication authentication){return bindings.findByUsernameAndProfileType(authentication.getName(),"STUDENT").filter(x->"ACTIVE".equals(x.getStatus())).map(x->x.getProfileId()).orElseThrow(()->new AccessDeniedException("当前账号不是有效学生账号"));} }
